```go
package cache

import "container/list"

// LRU is a fixed-capacity Least Recently Used cache.
type LRU struct {
    capacity int
    items    map[string]*list.Element
    list     *list.List
}

// entry represents a node in the LRU list.
type entry struct {
    key   string
    value int
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
    return &LRU{
        capacity: capacity,
        items:    make(map[string]*list.Element),
        list:     list.New(),
    }
}

// Get retrieves the value associated with the given key.
// If the key exists, it is moved to the most recently used position.
// It returns the value and true if found, or 0 and false otherwise.
func (c *LRU) Get(key string) (int, bool) {
    if elem, ok := c.items[key]; ok {
        c.list.MoveToFront(elem)
        return elem.Value.(*entry).value, true
    }
    return 0, false
}

// Put adds a key-value pair to the cache.
// If the key already exists, its value is updated and it becomes the most recently used.
// If the cache is full, the least recently used item is evicted.
func (c *LRU) Put(key string, value int) {
    if elem, ok := c.items[key]; ok {
        elem.Value.(*entry).value = value
        c.list.MoveToFront(elem)
        return
    }

    // New item
    if c.list.Len() == c.capacity {
        // Evict LRU
        back := c.list.Back()
        if back != nil {
            c.list.Remove(back)
            delete(c.items, back.Value.(*entry).key)
        }
    }

    // Add new item to front
    e := &entry{key: key, value: value}
    elem := c.list.PushFront(e)
    c.items[key] = elem
}

// Len returns the number of items in the cache.
func (c *LRU) Len() int {
    return c.list.Len()
}
